#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# W009 F2 (pre-registered in experiments/W009-wallet-prove-speed/README.md, "F2"): three memory-only steps in the GBP prover.
#   f2-1: free (zeroized) the l and r polynomials right after evaluation; f2-2: + shrink each cg weight vector;
#   f2-3: + move the commitment values into l instead of cloning.
# 1. build each arm's native wallet-rpc in ~/work/monerodato-f/build/native, copy to bins/;
# 2. VmHWM after 8/32/128 inputs, dot3 + the three arms, fresh process per arm and round, 3 rotated rounds;
# 3. proof differential: f2-3's GBP in a copy of the dot3-diff harness workspace, 258 cases against arm A's saved proofs;
# 4. the generalized-bulletproofs, fcmps and monero-fcmp-plus-plus crate tests on that copy.
set -u
source $HOME/.cargo/env
D=$HOME/work/wprof; F=$HOME/work/monerodato-f; X=$HOME/work/dot3-diff
G=src/fcmp_pp/fcmp_pp_rust/patched/monero-oxide/crypto/generalized-bulletproofs/src/arithmetic_circuit_proof.rs
[ -d "$F" ] && [ -d "$D" ] && [ -d "$X" ] || { echo "ABORT: not on the work box (missing $F, $D or $X)"; exit 1; }
mkdir -p $D/bins
# ninja does not track the patched crates' sources, so a branch switch alone does not re-run cargo (first start of this
# chain built nothing). Remove the Rust library so ninja re-runs cargo; cargo then rebuilds what changed. Each arm must
# show generalized-bulletproofs compiled and a binary different from the previous arm's.
prev=$(sha256sum $F/build/native/bin/monero-wallet-rpc | cut -c1-64)
for arm in f2-1 f2-2 f2-3; do
  echo "BUILD $arm $(date -u +%FT%TZ)"
  git -C $F checkout -q $arm || { echo BUILD_FAIL checkout $arm; exit 1; }
  rm -f $F/build/native/src/fcmp_pp/fcmp_pp_rust/libfcmp_pp_rust.a
  nice ninja -C $F/build/native -j10 wallet_rpc_server > $D/f2_build_$arm.log 2>&1 || { echo BUILD_FAIL $arm; exit 1; }
  grep -q "Compiling generalized-bulletproofs" $D/f2_build_$arm.log || { echo "BUILD_FAIL $arm: generalized-bulletproofs not recompiled"; exit 1; }
  cur=$(sha256sum $F/build/native/bin/monero-wallet-rpc | cut -c1-64)
  [ "$cur" != "$prev" ] || { echo "BUILD_FAIL $arm: binary unchanged"; exit 1; }
  prev=$cur
  mkdir -p $D/bins/$arm && cp $F/build/native/bin/monero-wallet-rpc $D/bins/$arm/
  sha256sum $D/bins/$arm/monero-wallet-rpc
done
W_dot3=$HOME/work/monerodato-dot3/build/native/bin/monero-wallet-rpc
run_arm() {
  arm=$1; bin=$2; rep=$3
  if ss -ltn 2> /dev/null | grep -q ":28497 "; then echo "ABORT: port 28497 already in use before $arm r$rep"; exit 1; fi
  rm -rf $D/wallets_f2m; mkdir -p $D/wallets_f2m; chmod 700 $D/wallets_f2m; cp -p $D/wallets/w006 $D/wallets/w006.keys $D/wallets_f2m/
  $bin --testnet --wallet-dir $D/wallets_f2m --daemon-address 127.0.0.1:28481 --trusted-daemon --rpc-bind-ip 127.0.0.1 --rpc-bind-port 28497 \
    --disable-rpc-login --non-interactive --log-file $D/wm_f2_$arm.log > /dev/null 2>&1 &
  P=$!
  for i in $(seq 1 60); do curl -s -m 3 http://127.0.0.1:28497/json_rpc -d "{\"jsonrpc\":\"2.0\",\"id\":0,\"method\":\"get_version\"}" | grep -q result && break; sleep 1; done
  (cd $D && python3 -I memprobe.py 28497 $P ${arm}_r$rep mem_f2.csv 8,32,128)
  kill $P; wait $P 2> /dev/null; rm -rf $D/wallets_f2m
  for i in $(seq 1 30); do ss -ltn 2> /dev/null | grep -q ":28497 " || break; sleep 1; done
}
rm -f $D/mem_f2.csv
echo "MEM_START $(date -u +%FT%TZ)"
for rep in 1 2 3; do
  case $rep in 1) order="dot3 f2-1 f2-2 f2-3";; 2) order="f2-3 dot3 f2-1 f2-2";; 3) order="f2-2 f2-3 dot3 f2-1";; esac
  for arm in $order; do
    if [ $arm = dot3 ]; then run_arm dot3 $W_dot3 $rep; else run_arm $arm $D/bins/$arm/monero-wallet-rpc $rep; fi
  done
done
echo "MEM_END $(date -u +%FT%TZ)"
# 3. differential
rm -rf $X/mo-F2 $X/out-F2; cp -a $X/mo $X/mo-F2
git -C $F show f2-3:$G > $X/mo-F2/crypto/generalized-bulletproofs/src/arithmetic_circuit_proof.rs
C="patch.crates-io.multiexp.path=\"$X/multiexp-A\""
(cd $X/mo-F2 && CARGO_TARGET_DIR=$X/target-F2 cargo +stable test --release -p full-chain-membership-proofs --no-run --config "$C" > $X/f2_build.log 2>&1) || { echo DIFF_BUILD_FAIL; exit 1; }
python3 -I $X/run_f2.py $X 10 > $X/f2_diff.log 2>&1; echo "DIFF rc=$?"; tail -6 $X/f2_diff.log
# 4. crate tests (non-ignored) on the F2 copy
(cd $X/mo-F2 && CARGO_TARGET_DIR=$X/target-F2 cargo +stable test --release -p generalized-bulletproofs -p full-chain-membership-proofs -p monero-fcmp-plus-plus --config "$C" > $X/f2_cratetests.log 2>&1); echo "CRATETESTS rc=$?"
grep -E "^test result" $X/f2_cratetests.log
echo "F2_DONE $(date -u +%FT%TZ)"
